    private static let household = DirectorySource(name: "Arbeiterkammer · Haushaltsversicherung", url: "https://ooe.arbeiterkammer.at/beratung/konsumentenschutz/versichern/Haushaltsversicherung.html")
    private static let householdClaim = DirectorySource(name: "Arbeiterkammer OÖ · Pflichten im Schadensfall", url: "https://ooe.arbeiterkammer.at/beratung/konsumentenschutz/versichern/Obliegenheiten-beachten-damit-Versicherung-zahlt.html")
    private static let car = DirectorySource(name: "Arbeiterkammer · Kfz-Versicherung", url: "https://www.arbeiterkammer.at/beratung/konsument/Versicherungen/versicherung-auswaehlen/Kfz-Versicherung.html")
    private static let travel = DirectorySource(name: "ÖGK · Urlaub im Ausland", url: "https://www.oegk.at/cdscontent/?contentid=10007.907080")
